import * as equilibrium from './equilibrium-model.js';
import {art} from './measurement-art.js';
import {equipmentArt} from './equipment-art.js';
import {calibrationGraph} from './measurement-review.js';
import {equilibriumQuestions,hlEquilibrium,equilibriumAssumptions} from './investigation-review.js';
import {reviewQuestions,bindReviewQuestions} from './review-questions.js';
import {initializeStorage} from './equipment-storage.js';
import {createEquipmentMenu} from './equipment-menu.js';
import {setArtwork} from './svg-render.js';
const $=id=>document.getElementById(id),M=equilibrium,mode='equilibrium',bench=$('bench'),layer=$('apparatus');
let state=initializeStorage(M.createState()),selected=null,drag=null,menu,last=0,note='',dataKey='',fineKey='';
const groups=new Map(),safe=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
for(const [id,o]of Object.entries(state.items)){const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.dataset.id=id;g.classList.add('object');g.setAttribute('tabindex','0');g.setAttribute('role','button');g.setAttribute('aria-label',o.name);g.addEventListener('focus',()=>select(id));groups.set(id,g);layer.append(g);}
$('equipment').innerHTML=Object.entries(state.items).map(([id,o])=>`<button class="equipment-button" data-equipment="${id}">${safe(o.name)}</button>`).join('');
for(const key of ['from','to'])$(key).innerHTML=Object.values(state.items).filter(o=>o.solutes).map(o=>`<option value="${o.id}">${safe(o.name)}</option>`).join('');
$('from').value='iron';$('to').value='mixture1';$('model-note').textContent=equilibriumAssumptions;
const certificates=Object.fromEntries(['reference1','reference2'].map(id=>[id,M.composition(state.items[id]).complex]));certificates.water=0;
function select(id){selected=id;note='';render();}
function renderData(){const key=JSON.stringify([state.records,state.unknownReadings,state.filter]);if(key===dataKey)return;dataKey=key;
 $('plot').innerHTML=calibrationGraph(state);$('measurements-head').innerHTML='<tr><th>Label / type</th><th>Entered c / M</th><th>A</th><th>Analytical Fe / M</th><th>Analytical SCN / M</th><th>Volume / mL</th><th>Conditions</th></tr>';
 $('measurements').innerHTML=[...state.records,...state.unknownReadings].sort((a,b)=>a.time-b.time).map(r=>`<tr><td>${safe(r.label)} · ${r.type==='standard'?'reference':'mixture'}</td><td>${r.concentration??'—'}</td><td>${r.absorbance.toFixed(3)}</td><td>${r.feTotal.toExponential(4)}</td><td>${r.scnTotal.toExponential(4)}</td><td>${r.volume.toFixed(4)}</td><td>${r.filter} · ${r.clean?'wiped':'unwiped'} · ${r.clearFace?'clear':'frosted'} · ${r.lid?'closed lid':'open lid'}</td></tr>`).join('');
 const estimate=M.estimate(state);$('data-summary').textContent=estimate?`Calibration-derived [complex] = ${estimate.value.toExponential(5)} mol dm⁻³${estimate.extrapolated?' · extrapolated; outside reference range':''}. Reference values are model certificates, not independent experimental validation of Kc.`:'Measure the solvent, both reference standards and an equilibrium mixture to obtain a calibration estimate.';
 const hl=hlEquilibrium(state);$('hl-content').innerHTML=hl?`<p>Use your calibration-derived x = ${hl.a.value.toPrecision(9)} M and recorded analytical totals Fe = ${hl.a.row.feTotal.toPrecision(9)} M, SCN = ${hl.a.row.scnTotal.toPrecision(9)} M.</p><label>Free [Fe³⁺] / M <input id="hl-fe" type="number" step="any"></label><label>Free [SCN⁻] / M <input id="hl-scn" type="number" step="any"></label><label>Kc / dm³ mol⁻¹ <input id="hl-k" type="number" step="any"></label>${hl.change&&Number.isFinite(hl.Q)?`<p>Most recently changed mixture: ${safe(hl.change.name)}. Immediately after its addition and dilution, before re-equilibration: [complex] = ${hl.change.immediate.toPrecision(9)} M; free Fe = ${(hl.change.feTotal-hl.change.immediate).toPrecision(9)} M; free SCN = ${(hl.change.scnTotal-hl.change.immediate).toPrecision(9)} M. Calculate Q and compare it with the model Kc = 890 to predict the direction.</p><label>Q / dm³ mol⁻¹ <input id="hl-q" type="number" step="any"></label><label>Predicted change <select id="hl-direction"><option value="forward">Forward</option><option value="reverse">Reverse</option><option value="at equilibrium">At equilibrium</option></select></label>`:''}<button id="check-hl" class="secondary">Check optional analysis</button><p id="hl-feedback" role="status"></p>`:'Record an in-range mixture reading with a physically usable calibration before attempting the optional HL calculations. The basic review remains available.';
}
function render(){const r=M.reading(state);
 for(const [id,g]of groups){const o=state.items[id];g.setAttribute('transform',`translate(${o.x} ${o.y}) rotate(${o.angle||0})`);setArtwork(g,art(o.solutes?{...o,displayColour:M.colour(o)}:o,state,r));g.classList.toggle('selected',id===selected);}
 if(selected&&groups.has(selected))layer.append(groups.get(selected));
 $('selected-name').textContent=state.items[selected]?.name||'Nothing selected';$('action').disabled=state.phase!=='working'||!M.active(state.items[selected]);$('action').textContent=state.items[selected]?.kind==='colorimeter'?(state.items.meter.lid?'Open lid':'Close lid'):state.items[selected]?.kind==='cuvette'?(state.items[selected].parent?'Remove cuvette':'Move to well & insert'):'Transfer selected vessel → receiver';
 const o=state.items[selected],fine=o?.kind==='cuvette'?'<button class="secondary" data-command="wipe">Wipe faces</button><button class="secondary" data-command="turn">Turn optical face</button><button class="secondary" data-command="drain">Drain to receiver</button>':'';if(fine!==fineKey){$('fine-controls').innerHTML=fine;fineKey=fine;}
 $('action-note').textContent=note||'Choose a source, receiver and measured portion; stored apparatus must be retrieved first.';
 $('live-reading').textContent=`A = ${r.value===null?'—':r.value.toFixed(3)}`;$('instrument-status').textContent=r.status;
 $('instrument').textContent=o?.solutes?`${o.water.toFixed(2)} mL${o.lastChange?' · complex '+o.lastChange.before.toExponential(3)+' → '+o.lastChange.after.toExponential(3)+' M':''}`:'';
 for(const id of ['transfer','record','record-standard','blank','certificate','finish','from','to','dose','filter','sample-label','known-concentration'])$(id).disabled=state.phase!=='working';
 for(const b of $('equipment').children)b.setAttribute('aria-pressed',String(b.dataset.equipment===selected));renderData();menu?.sync();
}
function transfer(from=$('from').value,ml=Number($('dose').value)){if(!Number.isFinite(ml)||ml<=0||ml>50){note='Choose a portion above zero and no greater than 50 mL.';return;}const n=M.transfer(state,from,$('to').value,ml);note=n?`Transferred ${n.toFixed(2)} mL. Added volume and analytical totals are accounted for.`:'Retrieve both vessels, remove a seated cuvette before filling, and choose different source/receiver vessels.';}
function action(command){if(state.phase!=='working')return;const o=state.items[selected];if(!M.active(o))return;
 if(o.kind==='colorimeter'){o.lid=!o.lid;note=o.lid?'Lid closed.':'Lid open.';}
 else if(o.kind==='cuvette'){
  if(command==='wipe'){o.clean=true;note='Faces wiped.';}else if(command==='turn'){o.clearFace=!o.clearFace;note=o.clearFace?'Clear face to beam.':'Frosted face to beam.';}
  else if(command==='drain')transfer(o.id,Math.max(0,o.water-.05));
  else if(o.parent)note=M.remove(state)?'Cuvette removed.':'Open the lid before removing the cuvette.';
  else if(!state.items.meter.lid&&!M.seated(state)&&M.active(state.items.meter)){o.x=state.items.meter.x+48;o.y=state.items.meter.y-10;note=M.insert(state,o.id)?'Cuvette seated. Close lid before measuring.':'Could not insert.';}else note='Open the lid and remove the previous cuvette first.';
 }else transfer(o.id);render();}
$('action').addEventListener('click',()=>action());$('fine-controls').addEventListener('click',e=>{const c=e.target.closest('[data-command]')?.dataset.command;if(c)action(c);});$('transfer').addEventListener('click',()=>{transfer();render();});
$('certificate').addEventListener('click',()=>{const id=$('from').value;if(id in certificates){$('known-concentration').value=certificates[id].toPrecision(10);note=`Original ${state.items[id].name} certificate: ${certificates[id].toExponential(5)} M. Only valid if unmodified.`;}else note='Choose Water or a supplied reference as the source. Your own mixtures have no supplied concentration certificate.';render();});
$('blank').addEventListener('click',()=>{note=M.blank(state)?'Optical reference recorded.':'Insert a filled cuvette.';render();});$('filter').addEventListener('change',e=>{state.filter=e.target.value;render();});
for(const [id,type]of [['record-standard','standard'],['record','unknown']])$(id).addEventListener('click',()=>{note=M.record(state,type,$('known-concentration').value,$('sample-label').value)?'Reading recorded.':'Obtain a valid optical reading; references also need an entered concentration.';render();});
$('hl-content').addEventListener('click',e=>{if(e.target.id!=='check-hl')return;const h=hlEquilibrium(state);if(!h)return;const near=(id,v)=>$(id)?.value.trim()!==''&&Math.abs(Number($(id).value)-v)<=Math.max(1e-8,Math.abs(v)*.02);const ok=near('hl-fe',h.a.fe)&&near('hl-scn',h.a.scn)&&near('hl-k',h.a.Kc)&&(!$('hl-q')||near('hl-q',h.Q)&&$('hl-direction').value===h.direction);$('hl-feedback').textContent=ok?'Correct for your recorded data. Compare measured Kc with the illustrative model value; optical errors and rounding can bias it.':'Use Fe_free = Fe_total − x, SCN_free = SCN_total − x; Kc = x/(Fe_free SCN_free), and Q from the immediately-after-addition concentrations.';});
$('equipment').addEventListener('click',e=>{const id=e.target.closest('[data-equipment]')?.dataset.equipment;if(id)select(id);});
const coords=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(bench.getScreenCTM().inverse());
bench.addEventListener('pointerdown',e=>{const id=e.target.closest('[data-id]')?.dataset.id;if(!id||e.button!==0||state.phase!=='working')return;select(id);const p=coords(e),o=state.items[id];drag={id,start:p,dx:p.x-o.x,dy:p.y-o.y,active:false};bench.setPointerCapture(e.pointerId);e.preventDefault();});
bench.addEventListener('pointermove',e=>{if(!drag)return;const p=coords(e);if(!drag.active){if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)<4)return;M.detach(state,drag.id);drag.active=true;}M.physicsFor(state).moveHeld(drag.id,Math.max(65,Math.min(935,p.x-drag.dx)),Math.max(15,Math.min(510,p.y-drag.dy)));render();});
function release(e){if(!drag)return;if(drag.active&&menu?.wantsStore(e)&&menu.store(drag.id))selected=null;else if(drag.active)M.placeItem(state);drag=null;render();}
bench.addEventListener('pointerup',release);bench.addEventListener('pointercancel',()=>release());
document.addEventListener('keydown',e=>{if(e.code!=='Space'||e.repeat||e.target.closest?.('input,select,textarea,button'))return;e.preventDefault();action();});
$('restart').addEventListener('click',()=>{release();state=initializeStorage(M.createState());selected=null;note='';dataKey='';$('result').hidden=true;$('result').innerHTML='';$('filter').value='blue';$('known-concentration').value='';render();});
$('finish').addEventListener('click',()=>{release();state.phase='finished';render();const questions=equilibriumQuestions(state);$('result').hidden=false;$('result').innerHTML='<h2>Review your equilibrium investigation</h2><p>Calibration estimates composition; this review is not evidence of mastery of an entire syllabus topic.</p>'+reviewQuestions(mode,questions);bindReviewQuestions(mode,()=>{state.phase='complete';},questions);$('result').focus({preventScroll:true});$('result').scrollIntoView({block:'nearest'});});
function frame(t){const dt=Math.min(.05,(t-last)/1000||.016);last=t;if(state.phase==='working'){M.stepPhysics(state,dt,drag?.active?drag.id:null);M.stepChemistry(state,dt);render();}requestAnimationFrame(frame);}
menu=createEquipmentMenu({getState:()=>state,getSelected:()=>selected,world:()=>M.physicsFor(state),groups,select,begin(id){select(id);M.detach(state,id);drag={id,active:true,dx:0,dy:0};},end:release,render,isDragging:()=>Boolean(drag?.active)});render();requestAnimationFrame(frame);
